def find_topmost_carpet(n, carpets, point) -> int:
    """
    Finds the topmost carpet covering a given point on the coordinate plane.

    Args:
        n (int): The total number of carpets.
        carpets (list of tuples): A list containing n tuples, each representing a carpet's information.
                                  Each tuple contains four integers (a, b, g, k) where (a, b) is the
                                  coordinates of the bottom-left corner of the carpet and (g, k) are
                                  the lengths of the carpet along the x and y axis respectively.
        point (tuple): A tuple containing two integers (x, y), the coordinates of the point to check.

    Returns:
        int: The number of the topmost carpet covering the point (x, y), or -1 if no carpet covers it.
    """
    try:
        if not isinstance(n, int) or n < 0:
            return -1
        if not isinstance(carpets, list) or len(carpets) != n:
            return -1
        if not isinstance(point, tuple) or len(point) != 2:
            return -1
        x, y = point
        if not (isinstance(x, int) and isinstance(y, int)):
            return -1

        topmost_index = -1
        for idx, carpet in enumerate(carpets, start=1):
            if (
                isinstance(carpet, tuple)
                and len(carpet) == 4
                and all(isinstance(v, int) for v in carpet)
            ):
                a, b, g, k = carpet
                # Ensure dimensions are non-negative
                if g < 0 or k < 0:
                    continue
                if a <= x <= a + g and b <= y <= b + k:
                    topmost_index = idx
            else:
                # Invalid carpet entry; skip
                continue
        return topmost_index
    except Exception:
        # In case of unexpected runtime errors, return -1
        return -1

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        TypeError: If inputs are of incorrect type.
        ValueError: If n is negative or coeffs length does not match n+1.
    """
    # Validate input types
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if not isinstance(coeffs, list):
        raise TypeError(f"coeffs must be a list, got {type(coeffs).__name__}")
    if n < 0:
        raise ValueError("n must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError(f"coeffs length must be {n + 1}, got {len(coeffs)}")
    for idx, c in enumerate(coeffs):
        if not isinstance(c, int):
            raise TypeError(f"coeffs[{idx}] must be an integer, got {type(c).__name__}")

    terms = []
    first_term = True
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    try:
        if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
            return "Failed"
        if len(encoded) != len(original):
            return "Failed"
        mapping = {}
        for e, o in zip(encoded, original):
            if e in mapping:
                if mapping[e] != o:
                    return "Failed"
            else:
                mapping[e] = o
        # Ensure all 26 uppercase letters are represented
        if len(mapping) != 26:
            return "Failed"
        # Optional: ensure mapping is bijective
        if len(set(mapping.values())) != 26:
            return "Failed"
        decoded_chars = []
        for ch in message:
            if ch not in mapping:
                return "Failed"
            decoded_chars.append(mapping[ch])
        return ''.join(decoded_chars)
    except Exception:
        return "Failed"

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).

    Args:
    x0 (int): The GCD that each pair (P, Q) must have.
    y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
    int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    # Validate inputs
    if not isinstance(x0, int) or not isinstance(y0, int):
        return 0
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    # Helper function for GCD
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    n = y0 // x0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            a = i
            b = n // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

