def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Returns the minimum number of steps required to transform A into B within 10 steps,
    or "NO ANSWER!" if impossible.
    """
    try:
        # Basic input validation
        if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
            return "NO ANSWER!"
        for rule in rules:
            if not (isinstance(rule, tuple) and len(rule) == 2 and
                    isinstance(rule[0], str) and isinstance(rule[1], str)):
                return "NO ANSWER!"
        # Immediate success
        if A == B:
            return 0
        # BFS initialization
        queue = [(A, 0)]
        index = 0
        visited = {A}
        max_depth = 10
        while index < len(queue):
            current, steps = queue[index]
            index += 1
            if steps >= max_depth:
                continue
            for src, tgt in rules:
                if src == "":
                    continue  # skip empty source to avoid infinite loops
                start = 0
                while True:
                    pos = current.find(src, start)
                    if pos == -1:
                        break
                    new_str = current[:pos] + tgt + current[pos + len(src):]
                    if new_str == B:
                        return steps + 1
                    if new_str not in visited:
                        visited.add(new_str)
                        queue.append((new_str, steps + 1))
                    start = pos + 1
        return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Basic type validation
    if not isinstance(scenario, str):
        raise TypeError("scenario must be a string")
    if not isinstance(liar_count, set):
        raise TypeError("liar_count must be a set")
    if not isinstance(statements, dict):
        raise TypeError("statements must be a dict")
    if not isinstance(days_of_week, set):
        raise TypeError("days_of_week must be a set")

    # Helper to determine truth value of a statement
    def evaluate_statement(speaker: str, stmt: str) -> bool:
        # Ignore statements about days of the week
        for day in days_of_week:
            if day in stmt:
                return None  # signal to ignore

        stmt = stmt.strip()
        # Direct patterns
        if stmt == "I am guilty.":
            return speaker == scenario
        if stmt == "I am not guilty.":
            return speaker != scenario

        # Patterns like "NAME is guilty." or "NAME is not guilty."
        parts = stmt.split()
        if len(parts) >= 3 and parts[1] == "is":
            name = parts[0]
            if parts[2] == "guilty.":
                return name == scenario
            if parts[2] == "not" and len(parts) >= 4 and parts[3] == "guilty.":
                return name != scenario
        # If statement cannot be parsed, ignore it
        return None

    try:
        for speaker, stmts in statements.items():
            if not isinstance(speaker, str):
                raise TypeError("speaker names must be strings")
            if not isinstance(stmts, list):
                raise TypeError("statements for each speaker must be a list")
            is_liar = speaker in liar_count
            for stmt in stmts:
                if not isinstance(stmt, str):
                    raise TypeError("each statement must be a string")
                truth = evaluate_statement(speaker, stmt)
                if truth is None:
                    continue  # ignore this statement
                if is_liar and truth:
                    return False  # liar told a true statement
                if not is_liar and not truth:
                    return False  # truth-teller told a false statement
        return True
    except Exception:
        # In case of unexpected errors, consider the scenario inconsistent
        return False

